    logger?: Logger;
    loggerLevel?: LoggerLevel;
    httpInstance?: HttpInstance;
    autoReconnect?: boolean;
    agent?: any;
    /** Caller tag appended to User-Agent as `source/<name>`. */
    source?: string;
    /** @internal Extra bare tokens appended to User-Agent, set by sub-modules. */
